import React, { useEffect, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import './NewLanding.css';
import { NewLandingHero } from './NewLandingHero';
import { NewLandingMid, MaskGroupBanner } from './NewLandingMid';

const LazyNewLandingFooter = React.lazy(() =>
  import('./NewLandingFooter').then((module) => ({ default: module.NewLandingFooter }))
);

export { MaskGroupBanner };

export const NewLanding = () => {
  const [isReady, setIsReady] = useState(false);
  const [showLoader, setShowLoader] = useState(true);

  useEffect(() => {
    let isMounted = true;
    const criticalImages = [
      `${process.env.PUBLIC_URL}/bg hero.avif`,
      `${process.env.PUBLIC_URL}/image.avif`,
      `${process.env.PUBLIC_URL}/hero bg new.avif`,
    ];

    const imagePromises = criticalImages.map(src => {
      return new Promise(resolve => {
        const img = new Image();
        img.decoding = 'async';
        img.src = src;
        if (img.complete) {
          resolve();
        } else {
          img.onload = () => resolve();
          img.onerror = () => resolve();
        }
      });
    });

    const fontPromise = document.fonts ? document.fonts.ready : Promise.resolve();
    const safetyTimeout = new Promise(resolve => setTimeout(resolve, 3500));

    Promise.race([
      Promise.all([...imagePromises, fontPromise]),
      safetyTimeout,
    ]).then(() => {
      if (!isMounted) return;
      setIsReady(true);
      setTimeout(() => {
        if (isMounted) setShowLoader(false);
      }, 500);
    });

    return () => {
      isMounted = false;
    };
  }, []);

  /* Scroll-in animation */
  useEffect(() => {
    if (!isReady) return;
    const targets = document.querySelectorAll('.nl-animate');
    const observer = new IntersectionObserver(
      entries => entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); }),
      { threshold: 0.08 }
    );
    targets.forEach(t => observer.observe(t));
    return () => observer.disconnect();
  }, [isReady]);

  return (
    <div className="nl-root">
      <AnimatePresence>
        {showLoader && !isReady && (
          <motion.div
            className="nl-loader-overlay"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
          >
            <div className="nl-loader-spinner" />
            <div className="nl-loader-logo">DISHASTRA</div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Render content only after critical assets are ready so entrance animations start cleanly from 0s right as the loader dissolves */}
      {isReady && (
        <>
          <NewLandingHero />
          <NewLandingMid />
          <React.Suspense fallback={null}>
            <LazyNewLandingFooter />
          </React.Suspense>
        </>
      )}
    </div>
  );
};
